<main class="page-shell registration-page"><div class="registration-header"><div><span class="eyebrow accent">REGISTRATION / 01</span><h1>Claim your<br><em>place.</em></h1><p><?= esc($event['name']) ?> · <?= esc($event['category_name']) ?></p></div><div class="registration-price"><span class="eyebrow">ENTRY FEE</span><strong><?= $event['fee'] > 0 ? esc(money($event['fee'])) : 'FREE' ?></strong><span class="mono">SECURE CHECKOUT</span></div></div><form method="post" action="<?= base_url('registration/'.$event['slug']) ?>" class="registration-form" data-testid="registration-form"><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><div class="form-section"><span class="eyebrow">01 / YOUR DETAILS</span><div class="form-grid"><label>Full name<input name="participant_name" value="<?= esc(old('participant_name')) ?>" required data-testid="registration-name-input"></label><label>Email address<input type="email" name="email" value="<?= esc(old('email')) ?>" required data-testid="registration-email-input"></label><label>Mobile number<input name="mobile" value="<?= esc(old('mobile')) ?>" required data-testid="registration-mobile-input"></label><label>College / institution<input name="college" value="<?= esc(old('college')) ?>" data-testid="registration-college-input"></label></div></div><div class="form-section"><span class="eyebrow">02 / EVENT CONFIGURATION</span><div class="form-grid"><label>Registration type<select name="registration_type" data-testid="registration-type-select"><option value="individual">Individual</option><option value="team">Team</option></select></label><label>Team name <span class="label-muted">(if applicable)</span><input name="team_name" data-testid="registration-team-input"></label><label class="full-field">Team member names <span class="label-muted">(one per line, team registrations only)</span><textarea name="team_member_names" data-testid="registration-team-members-input"></textarea></label><?php foreach ($fields as $field): ?><?php if(in_array($field['field_name'],['participant_name','email','mobile','college'],true)) continue; ?><label class="<?= $field['field_type']==='textarea'?'full-field':'' ?>"><?= esc($field['label']) ?><?= $field['is_required'] ? ' *' : '' ?><?php if ($field['field_type']==='textarea'): ?><textarea name="<?= esc($field['field_name']) ?>" placeholder="<?= esc($field['placeholder'] ?? '') ?>"></textarea><?php else: ?><input type="<?= in_array($field['field_type'],['email','number','date'],true)?esc($field['field_type']):'text' ?>" name="<?= esc($field['field_name']) ?>" placeholder="<?= esc($field['placeholder'] ?? '') ?>" <?= $field['is_required']?'required':'' ?>><?php endif ?></label><?php endforeach ?></div></div><div class="terms-row"><label class="checkbox-label"><input type="checkbox" required data-testid="registration-terms-checkbox"> <span>I agree to the event rules, privacy policy and refund terms.</span></label><button class="button button-yellow" type="submit" data-testid="registration-submit-button"><?= $event['fee'] > 0 ? 'Continue to payment' : 'Confirm registration' ?> <span>↗</span></button></div></form></main>